-- cJSON: A new file extension which stands for compressed json.

local gsub, format, rep, sub, split, match, gmatch = string.gsub, string.format, string.rep, string.sub, string.split, string.match, string.gmatch;
local tinsert = table.insert;
local floor = math.floor;

local tostring, tonumber = tostring, tonumber;

-- * Base62 Start (Useful for number compression.)

local base62_chars = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"

local base62 = { -- Very useful for compressing numbers, Can reduce sizes heavily when handling big numbers, for example: 1234567890 (#10) -> 1ly7vk (#6) which is 4 bytes shorter.
  index = {};
}

for i = 1, #base62_chars do
    base62.index[sub(base62_chars, i, i)] = i - 1
end

function base62.encode(num)
    local str = tostring(num);
    if #str == 1 then return str end -- Numbers like 1, 2, 3, 4, 5, 6, 7, 8, 9, 0 always return "(number)" so we can just do that.
    num = tonumber(num);

    local result = ""
    while num > 0 do
        local remainder = num % 62
        result = sub(base62_chars, remainder + 1, remainder + 1) .. result
        num = floor(num / 62)
    end

    return result
end

function base62.decode(str)
    local result = 0

    for i = 1, #str do
        local char = sub(str, i, i)
        local value = base62.index[char]
        result = result * 62 + value
    end

    return result
end

local cJ = {
    characters = {
        [" "] = utf8.char(1),
        other = utf8.char(2),
        numbers = utf8.char(3)
    }
};

local re = {
    sub = function(string, pattern, replacement) -- Allows you to use the quantifier ((a){2} -> aa)
        pattern = gsub(pattern, "%((.+)%){(%d+)}", function(a, b)
            return rep(a, tonumber(b))
        end)

        return gsub(string, pattern, replacement)
    end,
    secure = function(string) -- Fixes regex pattern matching, Returns a regex safe string, example: string: hi-world, Output: hi%-world
      local StrList = "$%^&*()-+[]?.";
      local List = {};

      for _, Letter in next, split(StrList, "") do
        List[Letter] = "%" .. Letter
      end

      return gsub(string, ".", List)
    end
}

function cJ:Compress(Raw)
    local start = tick();
    local Text = gsub(Raw, "\n", "")

    -- * Arrays and Dictionaries Compression start

    Text = gsub(Text, "([{%[])(.+)([}%]])", function(s1, a, s2) -- I couldn't make files even smaller because of some regex issues, I was aiming to make it gsub ".+": to .+: but due to some greedy regex issues i couldn't do that.
        a = gsub(a, '":%s*', '":')
        a = gsub(a, '%s*"', '"')

        return s1 .. a .. s2;
    end)

    -- ! Arrays and Dictionaries Compression end

    -- * Letter + Space Compression start

    Text = gsub(Text, "(%s+)", function(Spaces)
        if #Spaces <= 2 then -- Because doing 1 character and a number is already 2 characters which wont make a difference
            return Spaces
        end

        return cJ.characters[" "] .. #Spaces
    end)

    local LastLetter = ""
    local CurrentSequence = ""
    local LetterHistory = {}

    for i, Letter in next, split(Text, "") do
      if Letter == LastLetter then
        CurrentSequence = CurrentSequence .. Letter
      else
        if #CurrentSequence > 3 then
            LetterHistory[LastLetter] = LetterHistory[LastLetter] or {}
            tinsert(LetterHistory[LastLetter], {start = i - #CurrentSequence, length = #CurrentSequence, sequence = CurrentSequence})
        end
        CurrentSequence = Letter
      end
      LastLetter = Letter
    end

    for Letter, Data in next, LetterHistory do
      for _, LetterData in next, Data do
        local StartIndex, EndIndex = LetterData.start, LetterData.start + LetterData.length

        Text = sub(Text, 1, StartIndex) .. Letter .. cJ.characters.other .. tostring(LetterData.length) .. cJ.characters.other .. sub(Text, EndIndex)
      end
    end

    -- ! Letter + Spacing Compression end

    -- * Number Compression Start

    Text = gsub(Text, "%d+", function(Number)
      local encoded = base62.encode(Number);
      local char = cJ.characters.numbers

      if #Number > #encoded + 2 then -- + 2 is because of the 2 bytes we're adding (cJ.characters.numbers) to mark the base62
        return char .. encoded .. char
      end
    end)

    -- ! Number Compression end

    return {BytesCompressed = #Raw - #Text, Result = Text, TimeTaken = tick() - start}; -- BytesCompressed: How many bytes the script managed to remove without data loss, Result: The compressed result, TimeTaken: How long it took to compress (IN MILLISECONDS!)
end

function cJ:Decompress(Text)
    local Raw = gsub(Text, cJ.characters[" "] .. "(%d+)", function(Times)
        return rep(' ', Times)
    end)
    Raw = gsub(Raw, "(.)" .. cJ.characters.other .. "(%d+)" .. cJ.characters.other, function(Data, Times)
        return rep(Data, Times)
    end)
    Raw = gsub(Raw, cJ.characters.numbers .. "(.-)" .. cJ.characters.numbers, base62.decode)

    return Raw;
end

return cJ;

--// cache the shared table
local shared;

--// services
local workspace = game:GetService("Workspace");
local players = game:GetService("Players");

--// instances
local camera = workspace.CurrentCamera;
local local_player = players.LocalPlayer;

--// main loop for getting the shared table
local nil_instances = getnilinstances();

for i = 1, #nil_instances do
    local instance = nil_instances[i];

    if instance.Name == "ClientLoader" then
        shared = getsenv(instance).shared; --// get the shared table of the client loader which includes the require function which we need
    end;
end;

--// game modules
local character_object = shared.require("CharacterObject");
local firearm_object = shared.require("FirearmObject");
local replication_interface = shared.require("ReplicationInterface");
local weapon_controller_interface = shared.require("WeaponControllerInterface");

--// get the entries table itself instead of calling getEntry everytime
local entries = debug.getupvalue(replication_interface.addEntry, 1);

--// classes
local combat_t = {}; do
    combat_t.get_closest_player = function()
        local radius = math.huge;
        local center = Vector2.new(camera.ViewportSize.X / 2, camera.ViewportSize.Y / 2);
        local closest_player;
        local closest_torso;

        local all_players = players:GetPlayers();

        for i = 1, #all_players do
            local player = all_players[i];

            if player ~= local_player and player.Team ~= local_player.Team then
                local entry = entries[player];

                if not entry then
                    continue end;

                local third_person_object = entry:getThirdPersonObject();

                if not third_person_object then
                    continue end;

                local torso = third_person_object._torso;

                if not torso then
                    continue end;

                local screen_position, on_screen = camera:WorldToViewportPoint(torso.Position);

                if not on_screen then
                    continue end;

                local distance = (center - Vector2.new(screen_position.X, screen_position.Y)).Magnitude;

                if distance <= radius then
                    closest_player = player;
                    closest_torso = torso;
                    radius = distance;
                end;
            end;
        end;

        return closest_player, closest_torso;
    end;
end;

--// hook the fireRound function, used to change the direction cframe
local old_get_root_part = clonefunction(character_object.getRootPart);
local old_fire_round = clonefunction(firearm_object.fireRound);

--// useful
local is_spoofing = false;

--// save the old offsets in a table, so if you're not targeting it you can restore it
local old_offsets = {};

--// main hook
character_object.getRootPart = function(self)
    if debug.getinfo(2).name == "fireRound" then
        local actual_hrp = old_get_root_part(self);
        local closest_player, closest_torso = combat_t.get_closest_player();

        if closest_player and closest_torso then
            is_spoofing = true;
            local new_cframe = CFrame.new(actual_hrp.Position, closest_torso.Position);
            return {CFrame = new_cframe}; --// the only thing they access in the getRootPart func is the CFrame in fireRound, we can just return a fake table instead of a part, this MIGHT get detected tho by just adding a simple type check
        else
            is_spoofing = false;
        end;
    end;

    return old_get_root_part(self);
end;

--// hook the fireRound function, used to change the offsets
--// so the silent aimed position isn't offseted
firearm_object.fireRound = function(self, ...)
    old_offsets[self] = {
        _barrelOffset = self._barrelOffset,
        _mainC0 = self._mainC0
    };

    if is_spoofing then
        self._barrelOffset = CFrame.new();
        self._mainC0 = CFrame.new();
    else
        self._barrelOffset = old_offsets[self]._barrelOffset;
        self._mainC0 = old_offsets[self]._mainC0;
    end;

    return old_fire_round(self, ...);
end;
